-- Code generated by togo. PostgreSQL query fragment - safe to edit.
-- name: GetProxyHost :one
SELECT * FROM proxy_hosts WHERE id = $1;

-- name: ListProxyHosts :many
SELECT * FROM proxy_hosts ORDER BY created_at DESC LIMIT $1 OFFSET $2;

-- name: CreateProxyHost :one
INSERT INTO proxy_hosts (team_id, server_id, hostname, upstream, tls, enabled, websockets, verify_token, created_by)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
RETURNING *;

-- name: CreateBrowserProxyHost :one
-- A desktop browser's own hostname: not user-chosen upstream, and always forward_auth'd. tls is auto, or off on a server
-- with a private address (it sits behind an edge that terminates TLS and dials it over :80).
INSERT INTO proxy_hosts (team_id, server_id, hostname, upstream, tls, enabled, websockets, verify_token, created_by, browser_id, forward_auth)
VALUES (sqlc.arg('team_id'), sqlc.arg('server_id'), sqlc.arg('hostname'), sqlc.arg('upstream'), sqlc.arg('tls'), true, true,
    sqlc.arg('verify_token'), sqlc.arg('created_by'), sqlc.arg('browser_id'), sqlc.arg('forward_auth'))
RETURNING *;

-- name: DeleteProxyHost :exec
DELETE FROM proxy_hosts WHERE id = $1;

-- Hosbah tenant queries.
-- name: ListProxyHostsOfTeam :many
SELECT p.*, s.name AS server_name FROM proxy_hosts p JOIN servers s ON s.id = p.server_id
WHERE p.team_id = $1 ORDER BY p.hostname;

-- name: ListProxyHostsOfServer :many
SELECT * FROM proxy_hosts WHERE server_id = $1 AND team_id = $2 ORDER BY hostname;

-- name: ProxyHostInTeam :one
SELECT * FROM proxy_hosts WHERE team_id = sqlc.arg('team_id') AND (id = sqlc.arg('ref') OR hostname = sqlc.arg('ref'));

-- name: UpdateProxyHost :one
UPDATE proxy_hosts SET upstream = $3, tls = $4, enabled = $5, websockets = $6, updated_at = now()
WHERE id = $1 AND team_id = $2 RETURNING *;

-- name: MarkProxyHostVerified :exec
UPDATE proxy_hosts SET verified_at = now(), updated_at = now() WHERE id = $1 AND team_id = $2;

-- name: DeleteProxyHostInTeam :execrows
DELETE FROM proxy_hosts WHERE id = $1 AND team_id = $2;

-- name: ProxyHostByHostname :one
-- System scope only: forward_auth looks a hostname up before it knows the team (proxy_hosts has a
-- system SELECT policy for exactly this).
SELECT * FROM proxy_hosts WHERE hostname = sqlc.arg('hostname');

-- name: ProxyHostOfBrowser :one
-- Team scope: the proxy host a desktop browser owns, if any.
SELECT * FROM proxy_hosts WHERE browser_id = sqlc.arg('browser_id') AND team_id = sqlc.arg('team_id');
